/**
 * A typed client for the CurveVision REST API.
 *
 * Every path, parameter, request body and response is typed from the server's own OpenAPI
 * document (`schema.ts`, generated by `scripts/api_types.py` and checked against the
 * server in CI), so a call the server would refuse is usually a compile error first.
 *
 *     import { createClient } from '@curvevision/client';
 *
 *     const cv = createClient({ baseUrl: 'https://cv.example.com', token: 'cv_…' });
 *     const projects = await cv.call(cv.api.GET('/api/v1/projects'));
 *
 * `api` is an `openapi-fetch` client — `GET`, `POST`, `PATCH`, `PUT`, `DELETE`, each
 * returning `{ data, error, response }`. `call` unwraps one: the data, or a thrown
 * `CurveVisionError` carrying the server's problem document.
 */

import createFetchClient, { type Client, type Middleware } from 'openapi-fetch';
import type { components, paths } from './schema.js';

export type { components, paths };
/** A schema the API declares, by name: `Schema<'ProjectOut'>`. */
export type Schema<Name extends keyof components['schemas']> = components['schemas'][Name];

/** An RFC 9457 problem document, as every CurveVision error is. */
export interface Problem {
  type: string;
  title: string;
  status: number;
  detail: string;
  [extension: string]: unknown;
}

/** A request the server answered with an error, carrying its problem document. */
export class CurveVisionError extends Error {
  readonly status: number;
  readonly problem: Problem;

  constructor(status: number, problem: Problem) {
    super(problem.detail || problem.title || `HTTP ${status}`);
    this.name = 'CurveVisionError';
    this.status = status;
    this.problem = problem;
  }
}

export interface ClientOptions {
  /** The server's address, e.g. `https://cv.example.com` — without `/api/v1`. */
  baseUrl: string;
  /**
   * An API token (`cv_…`, made on the Workspace page or with `POST /api/v1/auth/tokens`)
   * or a session access token; sent as a bearer token. A function is asked on every
   * request, for a token that changes.
   */
  token?: string | (() => string | undefined | Promise<string | undefined>);
  /** A `fetch` to use instead of the global one. */
  fetch?: typeof globalThis.fetch;
}

export interface CurveVisionClient {
  /** The typed request functions: `api.GET('/api/v1/projects')`. */
  api: Client<paths>;
  /** The data of a request, or a thrown `CurveVisionError`. */
  call<T>(request: Promise<{ data?: T; error?: unknown; response: Response }>): Promise<T>;
}

function toProblem(status: number, error: unknown): Problem {
  if (error && typeof error === 'object' && 'title' in error) return error as Problem;
  const text = typeof error === 'string' ? error : JSON.stringify(error ?? null);
  return { type: 'about:blank', title: `HTTP ${status}`, status, detail: text };
}

export function createClient(options: ClientOptions): CurveVisionClient {
  const api = createFetchClient<paths>({
    baseUrl: options.baseUrl.replace(/\/+$/, ''),
    ...(options.fetch ? { fetch: options.fetch } : {}),
  });
  const { token } = options;
  if (token !== undefined) {
    const auth: Middleware = {
      async onRequest({ request }) {
        const value = typeof token === 'function' ? await token() : token;
        if (value) request.headers.set('Authorization', `Bearer ${value}`);
        return request;
      },
    };
    api.use(auth);
  }

  return {
    api,
    async call(request) {
      const { data, error, response } = await request;
      if (!response.ok || error !== undefined) {
        throw new CurveVisionError(response.status, toProblem(response.status, error));
      }
      return data as never;
    },
  };
}
